package ai.decisionos.aside;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.util.*;
final class SchoolWorkflowChecks {
 static void run(GoalInstrumentation i){Bundle out=new Bundle();GoalAgentActivity a=null;String gid="";List<String> cleanup=new ArrayList<>();String event=SchoolChatWork.eventId("portal","REGRESSION_EVENT","REGRESSION_학점교류");
 try(GoalStore store=new GoalStore(i.getTargetContext());CampusFlowStore campus=new CampusFlowStore(i.getTargetContext())){
  String[][] cases={{"notices","포털 학점교류 공지 정리해줘"},{"assignment","과제 대신 작성해줘"},{"bb_alerts","블랙보드 시험 오픈북 안내"},{"pdf","강의자료 PDF 한글 번역해줘"},{"team","팀플 발표자료 준비해줘"},{"application","메일 공모전 신청서 작성해줘"},{"professor","교수님께 병결 메일 써줘"},{"review","수강평 남겨줘"},{"course","강의평 읽고 수강 우선순위 정해줘"},{"community","캠퍼스픽 동아리 추천해줘"},{"books","이번 학기 교재 가격 비교해줘"},{"flirt","썸 답장 비교해줘"},{"lecture","강의 실시간 동시 통역해줘"},{"ktx","본가 가는 KTX 찾아줘"},{"concert","시험 끝나고 콘서트 찾아줘"},{"outfit","무신사 4910 옷 비교해줘"}};
  for(String[] x:cases)i.check(SchoolChatWork.match(x[1]).id.equals(x[0]),"natural-language routing "+x[0]);i.check(SchoolChatWork.match("안녕하세요")==null,"unknown instruction falls through");
  gid=store.create("grades","REGRESSION_SCHOOL_WORKFLOW","학교",0).optString("id");a=(GoalAgentActivity)i.startActivitySync(new Intent(i.getTargetContext(),GoalAgentActivity.class).putExtra("goal_id",gid).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final GoalAgentActivity host=a;i.runOnMainSync(()->host.relay.stop());
  for(String[] x:cases){i.runOnMainSync(()->i.check(SchoolChatWork.handle(host.chat,x[1]),"handled "+x[0]));}
  i.check(host.chat.history.length()==32,"requests and receipts retained in chat");for(JSONObject job:campus.list("jobs"))if(gid.equals(job.optString("goal"))){cleanup.add(job.optString("id"));i.check(job.optString("conversation").equals(host.chat.conversationId),"conversation ownership");i.check(job.optString("state").equals("draft"),"missing executor not marked complete");}
  i.check(cleanup.size()==16,"sixteen durable workflow receipts");i.waitForIdleSync();CompanionOnlyChecks.capture(i,"school-chat-workflows");try(GoalStore reopened=new GoalStore(i.getTargetContext())){i.check(reopened.workspaceRow("conversations",host.chat.conversationId).getJSONArray("messages").length()==32,"chat survives reopen");}
  SchoolChatWork.publish(i.getTargetContext(),"portal","REGRESSION_EVENT","REGRESSION_학점교류","TEST_OBSERVATION","https://portal.unist.ac.kr/","2026-11-01");long updated=campus.get(event).optLong("updated");SchoolChatWork.publish(i.getTargetContext(),"portal","REGRESSION_EVENT","REGRESSION_학점교류","TEST_OBSERVATION","https://portal.unist.ac.kr/","2026-11-01");i.check(campus.get(event).optLong("updated")==updated,"duplicate observed event ignored");i.check(campus.get(event).optString("origin").equals("observed"),"event provenance retained");i.runOnMainSync(host.chat::render);i.check(RedesignChecks.texts(host.chat.messages).contains("REGRESSION_학점교류"),"observed event appears in school chat");i.waitForIdleSync();CompanionOnlyChecks.capture(i,"school-chat-observed-event");
  out.putString("stream","PASS "+i.checks+" school workflow and observed-event checks\n");
 }catch(Throwable e){out.putString("stream","FAIL "+e+"\n");}finally{if(a!=null){final GoalAgentActivity host=a;i.runOnMainSync(host::finish);}try(CampusFlowStore s=new CampusFlowStore(i.getTargetContext())){for(String id:cleanup)s.remove(id);s.remove(event);}if(!gid.isEmpty())try(GoalStore s=new GoalStore(i.getTargetContext())){s.deleteGoal(gid);}}
 i.finish(out.getString("stream","").startsWith("PASS")?-1:0,out);}
}
